threejs-shaders.body:
# Three.js Shaders

## ShaderMaterial vs RawShaderMaterial

- **ShaderMaterial**: Three.js auto-injects built-in uniforms (`projectionMatrix`, `modelViewMatrix`, `normalMatrix`, `cameraPosition`) and precision headers. Use this 99% of the time.
- **RawShaderMaterial**: No auto-injection — you write everything. Use when you need full control.

## Minimal ShaderMaterial

```js
const mat = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColor: { value: new THREE.Color(0x4488ff) },
  },
  vertexShader: /* glsl */ `
    uniform float uTime;
    varying vec2 vUv;
    varying vec3 vNormal;

    void main() {
      vUv = uv;
      vNormal = normalize(normalMatrix * normal);

      vec3 pos = position;
      pos.y += sin(pos.x * 3.0 + uTime) * 0.1;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: /* glsl */ `
    uniform vec3 uColor;
    varying vec2 vUv;
    varying vec3 vNormal;

    void main() {
      float light = dot(vNormal, normalize(vec3(1.0, 1.0, 1.0))) * 0.5 + 0.5;
      gl_FragColor = vec4(uColor * light, 1.0);
    }
  `,
});

// Update uniforms in render loop
function animate() {
  requestAnimationFrame(animate);
  mat.uniforms.uTime.value = clock.getElapsedTime();
  renderer.render(scene, camera);
}
```

## Uniform Types

```glsl
// In JS:
uniforms: {
  uFloat:   { value: 1.0 },
  uVec2:    { value: new THREE.Vector2(0, 0) },
  uVec3:    { value: new THREE.Vector3(1, 0, 0) },
  uVec4:    { value: new THREE.Vector4() },
  uColor:   { value: new THREE.Color(0xff0000) },
  uMatrix:  { value: new THREE.Matrix4() },
  uTexture: { value: texture },           // sampler2D
  uCubemap: { value: cubeTexture },       // samplerCube
  uBool:    { value: true },              // bool (avoid — use float

threejs-xr.body:
# Three.js WebXR

## VR Setup

```js
import { VRButton } from "three/addons/webxr/VRButton.js";

renderer.xr.enabled = true;
document.body.appendChild(VRButton.createButton(renderer));

// XR render loop — use setAnimationLoop instead of requestAnimationFrame
renderer.setAnimationLoop(() => {
  renderer.render(scene, camera);
});
// setAnimationLoop replaces requestAnimationFrame for XR — both VR and non-VR work
```

## AR Setup

```js
import { ARButton } from "three/addons/webxr/ARButton.js";

renderer.xr.enabled = true;

// AR with hit testing
document.body.appendChild(
  ARButton.createButton(renderer, {
    requiredFeatures: ["hit-test"],
    optionalFeatures: ["dom-overlay"],
    domOverlay: { root: document.body },
  }),
);

renderer.setAnimationLoop((timestamp, frame) => {
  if (frame) {
    const referenceSpace = renderer.xr.getReferenceSpace();
    const session = renderer.xr.getSession();
    // hit test, place objects, etc.
  }
  renderer.render(scene, camera);
});
```

## Controllers

```js
// Controller 0 = right hand (usually), 1 = left hand
const controller1 = renderer.xr.getController(0);
const controller2 = renderer.xr.getController(1);
scene.add(controller1);
scene.add(controller2);

// Visual model for controllers
import { XRControllerModelFactory } from "three/addons/webxr/XRControllerModelFactory.js";
const controllerModelFactory = new XRControllerModelFactory();

const grip1 = renderer.xr.getControllerGrip(0);
grip1.add(controllerModelFactory.createControllerModel(grip1));
scene.add(grip1);

// Controller ray line
const geometry = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(0, 0, 0),
  new THREE.Vector3(0, 0, -1),
]);
const line = new THREE.Line(
  geometry,
  new THREE.LineBasicMaterial({ color: 0xffffff }),
);
line.scale.z = 5;
